//! 🧾️ Original JSON source paths, relational backing and partially attached trees remain in paid typed custody.
use super::{JsonSnapshot,JsonValue,JsonMember,kind};
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::receiving::{Direction,Projection,Scalar,AuthoredTable,cell,text_cell,row,push_row,sort,sort_charged,ordinal,integer,identity_position,parent_range,validate_schema,check_database,settle}};
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::NativeSnapshotBodyWallet;
use std::{mem::size_of,cell::{Cell,RefCell},cmp::Ordering};
type Result<T>=std::result::Result<T,ValueError>;
type Port<'a,'b,'c>=semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::Port<'a,'b,'c,NativeSnapshotBodyWallet>;
const SQL:&str=include_str!("../🗄️.sql");
const NAMES:[&str;4]=["json_document","json_value","json_object_member","json_array_element"];
fn error(kind:ValueRefusalKind,message:&'static str)->ValueError{ValueError::literal(kind,message)}
fn invalid(message:&'static str)->ValueError{error(ValueRefusalKind::InvalidValue,message)}
fn extent(value:usize,amount:usize)->Result<usize>{value.checked_add(amount).ok_or_else(||error(ValueRefusalKind::WorkLimit,"JSON original extent overflow"))}
fn definition(index:usize)->&'static str{SQL.split(';').filter(|s|!s.trim().is_empty()).nth(index).unwrap().trim()}
fn table<'a>(database:&'a SqliteDatabase,index:usize)->Result<&'a SqliteTable>{database.tables.iter().find(|t|t.name.eq_ignore_ascii_case(NAMES[index])).ok_or_else(||invalid("JSON authored table is missing"))}
fn text(row:&SqliteRow,column:usize)->Result<&str>{match row.values.get(column){Some(SqliteValue::Text(value))=>Ok(value),_=>Err(invalid("JSON literal text cell is invalid"))}}
fn empty()->JsonSnapshot{JsonSnapshot{schema:String::new(),value:JsonValue::Null}}
fn numeric(lexeme:&str,port:&mut Port<'_,'_,'_>)->Result<Option<f64>>{Ok(crate::standards::v_rfc8259::subsets::base::schema::snapshot::number::meaning(lexeme,&mut ||port.work(1,0))?.numeric)}
fn compare_text(left:&str,right:&str,port:&mut Port<'_,'_,'_>)->Result<Ordering>{for(a,b)in left.as_bytes().chunks(256).zip(right.as_bytes().chunks(256)){port.work(1,0)?;let comparison=a.cmp(b);if comparison!=Ordering::Equal{return Ok(comparison)}}Ok(left.len().cmp(&right.len()))}
#[derive(semio_framework_value::RetireOwned,Clone,Copy)]
struct Step{index:usize,next:usize,descriptor:usize,parent:usize,entered:bool}
#[derive(semio_framework_value::RetireOwned,Clone,Copy)]
struct Node{parent:usize,ordinal:usize,depth:usize}
fn at_path<'s>(source:&'s JsonValue,nodes:&[Node],path:&mut Vec<usize>,mut position:usize,port:&mut Port<'_,'_,'_>)->Result<&'s JsonValue>{while !path.is_empty(){port.work(1,size_of::<usize>())?;path.pop();}while nodes[position].parent!=usize::MAX{port.work(1,size_of::<usize>())?;if path.len()==path.capacity(){return Err(error(ValueRefusalKind::DepthLimit,"JSON original descriptor exceeds parent depth"))}path.push(nodes[position].ordinal);position=nodes[position].parent;}let mut value=source;for index in path.iter().rev(){port.work(1,0)?;value=match value{JsonValue::Array{items}=>items.get(*index),JsonValue::Object{members}=>members.get(*index).map(|member|&member.value),_=>None}.ok_or_else(||invalid("JSON retained source descriptor is invalid"))?;}Ok(value)}
fn key_path<'s>(source:&'s JsonValue,nodes:&[Node],path:&mut Vec<usize>,position:usize,port:&mut Port<'_,'_,'_>)->Result<Option<&'s str>>{let node=nodes[position];if node.parent==usize::MAX{return Ok(None)}match at_path(source,nodes,path,node.parent,port)?{JsonValue::Object{members}=>Ok(Some(&members[node.ordinal].key)),_=>Ok(None)}}
#[derive(semio_framework_value::RetireOwned)]
struct SourceIndex{nodes:Vec<Node>,walk:Vec<Step>,path:Vec<usize>,counts:[usize;4],children:Vec<usize>,members:Vec<usize>,duplicates:Vec<u8>}
impl SourceIndex{
 fn new()->Self{Self{nodes:Vec::new(),walk:Vec::new(),path:Vec::new(),counts:[1,0,0,0],children:Vec::new(),members:Vec::new(),duplicates:Vec::new()}}
 fn start(&mut self,port:&mut Port<'_,'_,'_>)->Result<()>{port.work(1,size_of::<Step>())?;if self.walk.capacity()==0{return Err(error(ValueRefusalKind::DepthLimit,"JSON original source path has no depth"))}self.walk.push(Step{index:0,next:0,descriptor:0,parent:usize::MAX,entered:false});Ok(())}
 fn walk_value<'s>(&self,source:&'s JsonValue,port:&mut Port<'_,'_,'_>)->Result<&'s JsonValue>{let mut value=source;for step in self.walk.iter().skip(1){port.work(1,0)?;value=match value{JsonValue::Array{items}=>items.get(step.index),JsonValue::Object{members}=>members.get(step.index).map(|member|&member.value),_=>None}.ok_or_else(||invalid("JSON original source path is invalid"))?;}Ok(value)}
 fn next(&mut self,source:&JsonValue,port:&mut Port<'_,'_,'_>)->Result<bool>{while !self.walk.is_empty(){port.work(self.walk.len(),0)?;if !self.walk.last().unwrap().entered{self.walk.last_mut().unwrap().entered=true;return Ok(true)}let count=match self.walk_value(source,port)?{JsonValue::Array{items}=>items.len(),JsonValue::Object{members}=>members.len(),_=>0};let last=*self.walk.last().unwrap();if last.next<count{let depth=extent(self.walk.len(),1)?;port.work(depth,size_of::<Step>())?;if self.walk.len()==self.walk.capacity(){return Err(error(ValueRefusalKind::DepthLimit,"JSON original source exceeds parent depth"))}self.walk.last_mut().unwrap().next+=1;self.walk.push(Step{index:last.next,next:0,descriptor:0,parent:last.descriptor,entered:false});}else{port.work(1,size_of::<Step>())?;self.walk.pop();}}Ok(false)}
 fn at<'s>(&mut self,source:&'s JsonValue,position:usize,port:&mut Port<'_,'_,'_>)->Result<&'s JsonValue>{at_path(source,&self.nodes,&mut self.path,position,port)}
 fn key<'s>(&mut self,source:&'s JsonValue,position:usize,port:&mut Port<'_,'_,'_>)->Result<Option<&'s str>>{key_path(source,&self.nodes,&mut self.path,position,port)}
 fn build(&mut self,source:&JsonSnapshot,port:&mut Port<'_,'_,'_>)->Result<()>{let depth=port.body.remaining_grant().maximum_depth;port.vector(depth,&mut self.walk,1)?;port.vector(depth,&mut self.path,1)?;self.start(port)?;while self.next(&source.value,port)?{let id=self.counts[1];self.walk.last_mut().unwrap().descriptor=id;self.counts[1]=extent(id,1)?;match self.walk_value(&source.value,port)?{JsonValue::Array{items}=>self.counts[3]=extent(self.counts[3],items.len())?,JsonValue::Object{members}=>self.counts[2]=extent(self.counts[2],members.len())?,_=>{}}port.control.check_rows(self.counts.iter().try_fold(0,|n,count|extent(n,*count))?)?;}port.vector(self.counts[1],&mut self.nodes,1)?;self.start(port)?;while self.next(&source.value,port)?{let step=*self.walk.last().unwrap();port.work(self.walk.len(),size_of::<Node>())?;let position=self.nodes.len();self.nodes.push(Node{parent:step.parent,ordinal:step.index,depth:self.walk.len()});self.walk.last_mut().unwrap().descriptor=position;}Ok(())}
 fn validation_indices(&mut self,source:&JsonSnapshot,port:&mut Port<'_,'_,'_>)->Result<()>{port.vector(self.nodes.len().saturating_sub(1),&mut self.children,1)?;port.vector(self.counts[2],&mut self.members,1)?;port.vector(self.nodes.len(),&mut self.duplicates,1)?;for index in 0..self.nodes.len(){port.work(1,size_of::<u8>())?;self.duplicates.push(0);if index>0{port.work(1,size_of::<usize>())?;self.children.push(index);if self.key(&source.value,index,port)?.is_some(){port.work(1,size_of::<usize>())?;self.members.push(index);}}}sort(&mut self.children,port,|a,b|Ok(self.nodes[a].parent.cmp(&self.nodes[b].parent).then(self.nodes[a].ordinal.cmp(&self.nodes[b].ordinal))))?;let nodes=&self.nodes;let path=&mut self.path;sort_charged(&mut self.members,port,|a,b,port|{let comparison=nodes[a].parent.cmp(&nodes[b].parent);if comparison!=Ordering::Equal{return Ok(comparison)}let left=key_path(&source.value,nodes,path,a,port)?.unwrap();let right=key_path(&source.value,nodes,path,b,port)?.unwrap();Ok(compare_text(left,right,port)?.then(nodes[a].ordinal.cmp(&nodes[b].ordinal)))})?;for index in 1..self.members.len(){let(a,b)=(self.members[index-1],self.members[index]);if self.nodes[a].parent==self.nodes[b].parent{let left=self.key(&source.value,a,port)?.unwrap();let right=self.key(&source.value,b,port)?.unwrap();if compare_text(left,right,port)?==Ordering::Equal{port.work(1,size_of::<u8>())?;self.duplicates[b]=1;}}}Ok(())}
}
#[derive(semio_framework_value::RetireOwned)]
struct Projected{projection:Projection,source:SourceIndex}
impl Projected{fn new()->Self{Self{projection:Projection::new(),source:SourceIndex::new()}}}
fn project(source:&JsonSnapshot,frame:&mut Projected,port:&mut Port<'_,'_,'_>)->Result<()>{frame.source.build(source,port)?;let counts=frame.source.counts;let schema_bytes=(0..4).map(|index|NAMES[index].len()+definition(index).len()).sum::<usize>();let limits=port.control.limits();if limits.max_tables<4||limits.max_columns<6||schema_bytes>limits.max_schema_bytes{return Err(error(ValueRefusalKind::OwnershipLimit,"JSON authored schema exceeds original ceiling"))}port.vector(4,&mut frame.projection.database.tables,1)?;for index in 0..4{port.work(2,size_of::<SqliteTable>())?;frame.projection.database.tables.push(SqliteTable{name:String::new(),sql:String::new(),rows:Vec::new()});let table=&mut frame.projection.database.tables[index];port.text(NAMES[index],&mut table.name,2)?;port.text(definition(index),&mut table.sql,2)?;port.vector(counts[index],&mut table.rows,2)?;}row(&mut frame.projection,1,3,port)?;text_cell(&mut frame.projection,&source.schema,port)?;cell(&mut frame.projection,Scalar::Integer(1),port)?;push_row(&mut frame.projection,0,port)?;
 for position in 0..frame.source.nodes.len(){let value=frame.source.at(&source.value,position,port)?;row(&mut frame.projection,ordinal(extent(position,1)?)?,6,port)?;text_cell(&mut frame.projection,kind(value),port)?;cell(&mut frame.projection,match value{JsonValue::Bool{value}=>Scalar::Integer(i64::from(*value)),_=>Scalar::Null},port)?;match value{JsonValue::Number{lexeme}=>text_cell(&mut frame.projection,lexeme,port)?,_=>cell(&mut frame.projection,Scalar::Null,port)?}match value{JsonValue::String{value}=>text_cell(&mut frame.projection,value,port)?,_=>cell(&mut frame.projection,Scalar::Null,port)?}cell(&mut frame.projection,match value{JsonValue::Number{lexeme}=>numeric(lexeme,port)?.map(Scalar::Real).unwrap_or(Scalar::Null),_=>Scalar::Null},port)?;push_row(&mut frame.projection,1,port)?;let node=frame.source.nodes[position];if node.parent!=usize::MAX{let key=frame.source.key(&source.value,position,port)?;let index=if key.is_some(){2}else{3};let id=ordinal(extent(frame.projection.database.tables[index].rows.len(),1)?)?;row(&mut frame.projection,id,if index==2{5}else{4},port)?;cell(&mut frame.projection,Scalar::Integer(ordinal(extent(node.parent,1)?)?),port)?;cell(&mut frame.projection,Scalar::Integer(ordinal(node.ordinal)?),port)?;if let Some(key)=key{text_cell(&mut frame.projection,key,port)?}cell(&mut frame.projection,Scalar::Integer(ordinal(extent(position,1)?)?),port)?;push_row(&mut frame.projection,index,port)?;}}
 let total=counts.iter().try_fold(0,|n,count|extent(n,*count))?;port.control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,total,total)
}

#[derive(semio_framework_value::RetireOwned,Clone,Copy)]
struct Visit{position:usize,finish:bool,depth:usize}
#[derive(semio_framework_value::RetireOwned)]
struct Reconstructed{snapshot:JsonSnapshot,ids:Vec<usize>,members:Vec<usize>,member_ids:Vec<usize>,elements:Vec<usize>,element_ids:Vec<usize>,owners:Vec<usize>,visited:Vec<u8>,candidates:Vec<Option<JsonValue>>,pending:Vec<Visit>,current:Option<JsonValue>,member:Option<JsonMember>}
impl Reconstructed{fn new()->Self{Self{snapshot:empty(),ids:Vec::new(),members:Vec::new(),member_ids:Vec::new(),elements:Vec::new(),element_ids:Vec::new(),owners:Vec::new(),visited:Vec::new(),candidates:Vec::new(),pending:Vec::new(),current:None,member:None}}}
fn index_rows(rows:&[SqliteRow],width:usize,ids:&mut Vec<usize>,port:&mut Port<'_,'_,'_>)->Result<()>{port.vector(rows.len(),ids,1)?;for(index,row)in rows.iter().enumerate(){port.work(1,0)?;if row.values.len()!=width||integer(row,0)?!=row.rowid{return Err(invalid("JSON entity identity or width is invalid"))}port.work(1,size_of::<usize>())?;ids.push(index);}sort(ids,port,|a,b|Ok(rows[a].rowid.cmp(&rows[b].rowid)))?;for pair in ids.windows(2){port.work(1,0)?;if rows[pair[0]].rowid==rows[pair[1]].rowid{return Err(invalid("JSON entity identity is duplicated"))}}Ok(())}
fn value_shape(row:&SqliteRow,port:&mut Port<'_,'_,'_>)->Result<()>{port.work(1,0)?;let empty=|index|matches!(row.values.get(index),Some(SqliteValue::Null));match text(row,1)?{"null"|"array"|"object" if empty(2)&&empty(3)&&empty(4)&&empty(5)=>{},"boolean" if empty(3)&&empty(4)&&empty(5)&&matches!(integer(row,2)?,0|1)=>{},"string" if empty(2)&&empty(3)&&empty(5)=>{text(row,4)?;},"number" if empty(2)&&empty(4)=>{let expected=numeric(text(row,3)?,port)?;let agrees=match expected{None=>empty(5),Some(expected)=>match row.values.get(5){Some(SqliteValue::Real(value))=>*value==expected,Some(SqliteValue::Integer(value))=>*value as f64==expected,_=>false}};if !agrees{return Err(invalid("JSON derived numeric value disagrees with its owned lexeme"))}},_=>return Err(invalid("JSON primitive kind and payload columns disagree"))}Ok(())}
fn ordered(rows:&[SqliteRow],indices:&mut Vec<usize>,port:&mut Port<'_,'_,'_>)->Result<()>{port.vector(rows.len(),indices,1)?;for index in 0..rows.len(){port.work(1,size_of::<usize>())?;indices.push(index);}sort(indices,port,|a,b|Ok(integer(&rows[a],1)?.cmp(&integer(&rows[b],1)?).then(integer(&rows[a],2)?.cmp(&integer(&rows[b],2)?))))?;let(mut parent,mut next)=(None,0);for index in indices{port.work(1,0)?;let row=&rows[*index];let id=integer(row,1)?;if parent!=Some(id){parent=Some(id);next=0}if integer(row,2)?!=ordinal(next)?{return Err(invalid("JSON child ordinals must be contiguous and zero-based"))}next=extent(next,1)?;}Ok(())}
fn prepare<'d>(database:&'d SqliteDatabase,frame:&mut Reconstructed,port:&mut Port<'_,'_,'_>)->Result<(usize,&'d SqliteRow,&'d[SqliteRow],&'d[SqliteRow],&'d[SqliteRow])>{let widths=[3,6,5,4];let authored=[0,1,2,3].map(|index|AuthoredTable{name:NAMES[index],declaration:definition(index),columns:widths[index]});validate_schema(database,&authored,port)?;check_database(database,port)?;let documents=&table(database,0)?.rows;if documents.len()!=1||documents[0].values.len()!=3||documents[0].rowid!=1||integer(&documents[0],0)?!=1{return Err(invalid("JSON document requires identifier one and three cells"))}let document=&documents[0];text(document,1)?;let values=&table(database,1)?.rows;let members=&table(database,2)?.rows;let elements=&table(database,3)?.rows;index_rows(values,6,&mut frame.ids,port)?;index_rows(members,5,&mut frame.member_ids,port)?;index_rows(elements,4,&mut frame.element_ids,port)?;for row in values{value_shape(row,port)?;}let root=identity_position(values,&frame.ids,integer(document,2)?,port)?.ok_or_else(||invalid("JSON document root is dangling"))?;port.vector(values.len(),&mut frame.owners,1)?;port.vector(values.len(),&mut frame.visited,1)?;for _ in values{port.work(1,size_of::<usize>()+size_of::<u8>())?;frame.owners.push(0);frame.visited.push(0);}frame.owners[root]=usize::MAX;ordered(members,&mut frame.members,port)?;ordered(elements,&mut frame.elements,port)?;for(rows,tag,column)in[(members,"object",4),(elements,"array",3)]{for row in rows{port.work(1,0)?;let parent=identity_position(values,&frame.ids,integer(row,1)?,port)?.ok_or_else(||invalid("JSON relationship parent is dangling"))?;let child=identity_position(values,&frame.ids,integer(row,column)?,port)?.ok_or_else(||invalid("JSON relationship child is dangling"))?;if text(&values[parent],1)?!=tag{return Err(invalid("JSON relationship parent kind differs"))}if tag=="object"{text(row,3)?;}if frame.owners[child]!=0{return Err(invalid("JSON value has multiple owners or creates a cycle"))}port.work(1,size_of::<usize>())?;frame.owners[child]=extent(parent,1)?;}}for owner in &frame.owners{port.work(1,0)?;if *owner==0{return Err(invalid("JSON value has no document or container owner"))}}Ok((root,document,values,members,elements))}
fn child_range(rows:&[SqliteRow],indices:&[usize],row:&SqliteRow,port:&mut Port<'_,'_,'_>)->Result<std::ops::Range<usize>>{parent_range(rows,indices,row.rowid,1,port)}
fn push_visit(frame:&mut Reconstructed,visit:Visit,port:&mut Port<'_,'_,'_>)->Result<()>{port.work(visit.depth,size_of::<Visit>())?;if frame.pending.len()==frame.pending.capacity(){return Err(error(ValueRefusalKind::WorkLimit,"JSON original visit capacity exhausted"))}frame.pending.push(visit);Ok(())}
fn reconstruct(database:&SqliteDatabase,frame:&mut Reconstructed,port:&mut Port<'_,'_,'_>)->Result<()>{let(root,document,values,members,elements)=prepare(database,frame,port)?;let schema=text(document,1)?;port.control.admit_reconstruction_bytes(schema.len())?;port.text(schema,&mut frame.snapshot.schema,1)?;port.vector(values.len(),&mut frame.candidates,1)?;port.vector(values.len().checked_mul(2).ok_or_else(||error(ValueRefusalKind::WorkLimit,"JSON original visit census overflow"))?,&mut frame.pending,1)?;for _ in values{port.work(1,size_of::<Option<JsonValue>>())?;frame.candidates.push(None);}push_visit(frame,Visit{position:root,finish:false,depth:1},port)?;
 while let Some(visit)=frame.pending.last().copied(){port.work(visit.depth,size_of::<Visit>())?;frame.pending.pop();let row=&values[visit.position];let tag=text(row,1)?;let(edges,indices,child_column)=if tag=="object"{(members,&frame.members,4)}else{(elements,&frame.elements,3)};let range=if matches!(tag,"object"|"array"){child_range(edges,indices,row,port)?}else{0..0};if !visit.finish{if frame.visited[visit.position]!=0{return Err(invalid("JSON relationships contain a cycle"))}port.work(1,size_of::<u8>())?;frame.visited[visit.position]=1;push_visit(frame,Visit{finish:true,..visit},port)?;for index in range.rev(){let edge_index=if tag=="object"{frame.members[index]}else{frame.elements[index]};let child=identity_position(values,&frame.ids,integer(&edges[edge_index],child_column)?,port)?.unwrap();push_visit(frame,Visit{position:child,finish:false,depth:extent(visit.depth,1)?},port)?;}continue;}
  port.work(visit.depth,size_of::<JsonValue>())?;frame.current=Some(match tag{"null"=>JsonValue::Null,"boolean"=>JsonValue::Bool{value:integer(row,2)?==1},"number"=>JsonValue::Number{lexeme:String::new()},"string"=>JsonValue::String{value:String::new()},"array"=>JsonValue::Array{items:Vec::new()},"object"=>JsonValue::Object{members:Vec::new()},_=>return Err(invalid("JSON value kind is invalid"))});match frame.current.as_mut().unwrap(){JsonValue::Number{lexeme}=>{let source=text(row,3)?;port.control.admit_reconstruction_bytes(source.len())?;port.text(source,lexeme,visit.depth)?;},JsonValue::String{value}=>{let source=text(row,4)?;port.control.admit_reconstruction_bytes(source.len())?;port.text(source,value,visit.depth)?;},JsonValue::Array{items}=>port.vector(range.len(),items,visit.depth)?,JsonValue::Object{members}=>port.vector(range.len(),members,visit.depth)?,_=>{}}
  for index in range{let edge_index=if tag=="object"{frame.members[index]}else{frame.elements[index]};let edge=&edges[edge_index];let child=identity_position(values,&frame.ids,integer(edge,child_column)?,port)?.unwrap();if frame.candidates[child].is_none(){return Err(invalid("JSON child was not reconstructed"))}if tag=="object"{port.work(visit.depth,size_of::<JsonMember>())?;frame.member=Some(JsonMember{key:String::new(),value:JsonValue::Null});let key=text(edge,3)?;port.control.admit_reconstruction_bytes(key.len())?;port.text(key,&mut frame.member.as_mut().unwrap().key,visit.depth)?;port.work(visit.depth,size_of::<JsonValue>())?;frame.member.as_mut().unwrap().value=frame.candidates[child].take().unwrap();port.work(visit.depth,size_of::<JsonMember>())?;let JsonValue::Object{members}=frame.current.as_mut().unwrap()else{unreachable!()};members.push(frame.member.take().unwrap());}else{port.work(visit.depth,size_of::<JsonValue>())?;let JsonValue::Array{items}=frame.current.as_mut().unwrap()else{unreachable!()};items.push(frame.candidates[child].take().unwrap());}}
  port.work(visit.depth,size_of::<Option<JsonValue>>()+size_of::<u8>())?;frame.candidates[visit.position]=frame.current.take();frame.visited[visit.position]=2;
 }
 for state in &frame.visited{port.work(1,0)?;if *state!=2{return Err(invalid("JSON relationships are disconnected or cyclic"))}}port.work(1,size_of::<JsonValue>())?;frame.snapshot.value=frame.candidates[root].take().unwrap();let total=database.tables.iter().try_fold(0,|n,table|extent(n,table.rows.len()))?;port.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,total,total)
}

struct Settlement<'a,'b>{control:RefCell<&'a mut SqliteSnapshotControl<'b>>,before:usize,remaining:usize,phase:SqliteSnapshotPhase,post_body:Cell<bool>,cause:RefCell<Option<ValueError>>}
impl<'a,'b>Settlement<'a,'b>{
 fn new(control:&'a mut SqliteSnapshotControl<'b>,before:usize,phase:SqliteSnapshotPhase)->Self{let remaining=control.allocation_remaining_bytes();Self{control:RefCell::new(control),before,remaining,phase,post_body:Cell::new(false),cause:RefCell::new(None)}}
 fn finish_body(&self,owned:usize)->Result<()>{settle(&mut self.control.borrow_mut(),self.remaining,self.before,owned)?;self.post_body.set(true);Ok(())}
 fn observe(&self,owned:usize,completed:usize,total:usize)->bool{if !self.post_body.get(){return true}let result={let mut control=self.control.borrow_mut();settle(&mut control,self.remaining,self.before,owned).and_then(|_|control.checkpoint(self.phase,completed,total))};match result{Ok(())=>true,Err(error)=>{*self.cause.borrow_mut()=Some(error);false}}}
 fn refused(&self,owned:usize,original:ValueError)->ValueError{match settle(&mut self.control.borrow_mut(),self.remaining,self.before,owned){Err(cause)=>cause,Ok(())=>self.cause.borrow_mut().take().unwrap_or(original)}}
}
fn receive_decoding<F:semio_framework_value::retirement::RetireOwned+'static,O:semio_framework_value::retirement::RetireOwned>(control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>,new:fn()->F,operation:impl FnOnce(&mut F,&mut Port<'_,'_,'_>)->Result<()>,take:impl FnOnce(&mut F)->O)->Result<O>{
 let result=(||{owner.native().checkpoint()?;let before=owner.native().owned_bytes();let maximum=before.checked_add(control.allocation_remaining_bytes()).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"JSON original SQL ceiling overflow"))?;let settlement=Settlement::new(control,before,SqliteSnapshotPhase::ProjectSnapshot);let mut observer=|event:semio_framework_value_native_owned::native_decoding::NativeDecodeProgress|settlement.observe(event.owned_bytes,event.completed,event.total);let result=owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<F,O>(|slot,native,body|{let mut control=settlement.control.borrow_mut();let mut port=Port{control:&mut control,native:Direction::Decode(native),body};port.work(1,size_of::<F>())?;*slot=Some(new());let frame=slot.as_mut().unwrap();operation(frame,&mut port)?;port.work(1,size_of::<O>())?;let owned=port.owned();drop(port);drop(control);settlement.finish_body(owned)?;Ok(take(frame))}));match result{Ok(value)=>Ok(value),Err(original)=>Err(settlement.refused(owner.native().owned_bytes(),original))}})();result.map_err(|error|error.with_retained_progress(owner.progress()))
}
