struct CountFormat<'a,'b,'c,'d>{port:&'a mut Port<'b,'c,'d>,bytes:usize,cause:&'a mut Option<ValueError>}
impl std::fmt::Write for CountFormat<'_,'_,'_,'_>{fn write_str(&mut self,text:&str)->std::fmt::Result{match self.port.work(1,0).and_then(|_|extent(self.bytes,text.len())){Ok(bytes)=>{self.bytes=bytes;Ok(())},Err(error)=>{*self.cause=Some(error);Err(std::fmt::Error)}}}}
struct PaidFormat<'a,'b,'c,'d>{port:&'a mut Port<'b,'c,'d>,output:&'a mut Vec<u8>,cause:&'a mut Option<ValueError>,total:usize}
