struct Validated{source:SourceIndex,diagnostics:Diagnostics,crs:Vec<u8>}
impl Validated{fn new()->Self{Self{source:SourceIndex::new(),diagnostics:Diagnostics::new(),crs:Vec::new()}}}
fn validation_prelude(source:&JsonSnapshot,dialect:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.stdio.json"||dialect.standard!="rfc8259"{return Err(error(ValueRefusalKind::UnsupportedOwner,"JSON owned snapshot dialect differs from RFC8259"))}if !matches!(dialect.subset.as_str(),"*"|"i-json"|"geojson"){return Err(error(ValueRefusalKind::UnsupportedOwner,"JSON named subset has no owned semantic validator"))}let documents=&table(database,0)?.rows;if documents.len()!=1||documents[0].rowid!=1{return Err(invalid("JSON owned document identity differs from semantic projection"))}let original=text(&documents[0],1)?;if original.len()!=source.schema.len(){return Err(invalid("JSON owned document identity differs from semantic projection"))}for(a,b)in original.as_bytes().chunks(256).zip(source.schema.as_bytes().chunks(256)){control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,original.len())?;if a!=b{return Err(invalid("JSON owned document identity differs from semantic projection"))}}Ok(())}
fn validate(source:&JsonSnapshot,subset:&str,frame:&mut Validated,port:&mut Port<'_,'_,'_>)->Result<()>{frame.source.build(source,port)?;match subset{"i-json"=>i_json(source,&mut frame.source,&mut frame.diagnostics,port),"geojson"=>geo_json(source,&mut frame.source,&mut frame.diagnostics,&mut frame.crs,port),_=>Err(error(ValueRefusalKind::InvariantViolated,"JSON receiving validator selection differs"))}}
pub(super)fn validate_decoding(source:&JsonSnapshot,dialect:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotDecodeOwner<'_,'_>)->store::io_schema::IoResult<()>{let result=(||{owner.native().checkpoint()?;validation_prelude(source,dialect,database,control)?;if dialect.subset=="*"{return Ok(Vec::new())}receive_decoding(control,owner,Validated::new,|frame,port|validate(source,&dialect.subset,frame,port),|frame|std::mem::take(&mut frame.diagnostics.output))})();result.map(|diagnostics|store::io_schema::IoOutcome{value:(),diagnostics}).map_err(|error|store::io_schema::IoError::from_value_error(error.with_retained_progress(owner.progress())))}
pub(super)fn validate_encoding(source:&JsonSnapshot,dialect:&semio_framework_artifact_reference::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,owner:&mut store::NativeSnapshotEncodeOwner<'_,'_>)->store::io_schema::IoResult<()>{let result=(||{owner.native().checkpoint()?;validation_prelude(source,dialect,database,control)?;if dialect.subset=="*"{return Ok(Vec::new())}receive_encoding(control,owner,Validated::new,|frame,port|validate(source,&dialect.subset,frame,port),|frame|std::mem::take(&mut frame.diagnostics.output))})();result.map(|diagnostics|store::io_schema::IoOutcome{value:(),diagnostics}).map_err(|error|store::io_schema::IoError::from_value_error(error.with_retained_progress(owner.progress())))}
